const $=id=>document.getElementById(id);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nice=x=>esc(String(x??'').replaceAll('_',' '));
const pill=x=>`<span class="pill ${esc(x)}">${nice(x)}</span>`;
const prettyDate=x=>new Date(x.replace(' ','T')).toLocaleDateString('en-CA',{weekday:'short',month:'short',day:'numeric',year:'numeric'});
const time=x=>x.slice(-5);const mins=x=>{const [h,m]=time(x).split(':').map(Number);return h*60+m;};
const route=location.pathname;const query=new URLSearchParams(location.search);let clinicId=query.get('clinic')||localStorage.getItem('octopus_clinic')||'REVIVE';if(!['REVIVE','BETHESDA'].includes(clinicId))clinicId='REVIVE';let state,selected=query.get('slot')||'S001',tab='eligible',day='';
const titles={'/clinic/':['Clinic dashboard','A quick overview of today’s appointments and opportunities.'],'/clinic/schedule':['Practitioner schedule','Click a booked appointment to cancel it or review its details.'],'/clinic/appointments':['Appointments','Find and manage existing appointments.'],'/clinic/matching':['Appointment recovery','Ranked patients, exclusions and simulated offers live here.'],'/clinic/approvals':['Approvals','Review temporary holds before confirming replacement appointments.']};
const title=titles[route]||titles['/clinic/'];$('pageTitle').textContent=title[0];$('pageSub').textContent=title[1];document.querySelectorAll('[data-route]').forEach(a=>a.classList.toggle('active',a.dataset.route===route));
async function req(url,opts){const r=await fetch(url,opts),j=await r.json();if(!r.ok)throw Error(j.error||'Request failed');return j;}
async function act(action,slot_id){try{await req('/api/clinic/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,slot_id,clinic_id:clinicId})});$('error').textContent='';await refresh();}catch(e){$('error').textContent=e.message;}}
const scheduleLink=id=>`/clinic/schedule?clinic=${encodeURIComponent(clinicId)}&slot=${encodeURIComponent(id)}`;
const recoveryLink=id=>`/clinic/matching?clinic=${encodeURIComponent(clinicId)}&slot=${encodeURIComponent(id)}`;
function appointment(s,actions=true){return `<div class="appointment-row"><div><div class="eyebrow">${esc(s.slot_id)} · ${esc(state.clinic_names[s.clinic_id]||s.clinic_id)}</div><strong>${nice(s.service_type)} · ${nice(s.visit_type)}</strong><div class="muted">${esc(prettyDate(s.start_at))} · ${time(s.start_at)}–${time(s.end_at)} · ${esc(s.provider_id)}${s.status==='booked'&&s.booked_patient_id?' · Patient: '+esc(state.patient_names[s.booked_patient_id]||s.booked_patient_id):''}</div></div><div class="row">${pill(s.status)}${actions&&s.status==='booked'?`<button class="danger smallbtn" data-cancel="${esc(s.slot_id)}">Cancel</button>`:''}${actions&&['open','offering','held'].includes(s.status)?`<a class="link-btn" href="${recoveryLink(s.slot_id)}">Recovery →</a>`:''}</div></div>`;}
function stats(){let l=state.slots;return `<div class="notice" style="margin-bottom:16px"><strong>${esc(state.clinic_names[clinicId])}</strong> · ${state.patients_at_clinic} fictional patients · ${l.length} scheduled appointments · ${new Set(l.map(x=>x.provider_id)).size} practitioners · ${new Set(l.map(x=>x.start_at.slice(0,10))).size} dates</div><div class="kpis">${[['Appointments',l.length],['Booked',l.filter(x=>x.status==='booked').length],['Open / offers out',l.filter(x=>['open','offering'].includes(x.status)).length],['Held / confirmed',l.filter(x=>['held','confirmed'].includes(x.status)).length]].map(([name,n])=>`<div class="kpi"><small>${esc(name)}</small><strong>${n}</strong><div class="muted">synthetic records</div></div>`).join('')}</div>`;}
function dashboard(){let openings=state.slots.filter(s=>['open','offering'].includes(s.status)),held=state.slots.filter(s=>s.status==='held');return stats()+`<div class="grid"><section class="card"><div class="flex"><h2>Recovery opportunities</h2><a class="textlink" href="/clinic/matching">View recovery →</a></div>${openings.length?openings.map(s=>`<div class="appointment-row"><div><strong>${nice(s.service_type)}</strong><div class="muted">${esc(s.slot_id)} · ${time(s.start_at)} · ${esc(s.provider_id)}</div></div><a class="link-btn" href="${recoveryLink(s.slot_id)}">Review matches →</a></div>`).join(''):'<div class="blank">No openings yet. Cancel a fictional appointment on the Schedule to see recovery begin.</div>'}<div class="divider"></div><a class="link-btn" href="/clinic/schedule">Open clinic schedule →</a></section><section class="card"><h2>Needs your attention</h2>${held.length?held.map(s=>appointment(s,false)).join(''):'<div class="blank">No pending approvals.</div>'}<p><a class="textlink" href="/clinic/approvals">Go to approvals →</a></p><div class="divider"></div><h2>How recovery works</h2><div class="steps">1. Cancel on schedule<br>2. Review matches in Recovery<br>3. Patient accepts offer<br>4. Confirm in Approvals</div></section></div>`;}
function makeCalendar(){const days=[...new Set(state.slots.map(s=>s.start_at.slice(0,10)))].sort();if(!days.includes(day))day=days[0];const slots=state.slots.filter(s=>s.start_at.startsWith(day));let providers=[...new Set(slots.map(s=>s.provider_id))].sort();if(!providers.length)return '<div class="blank">No appointments for this date.</div>';
const start=8*60,end=19*60,pixelsPerMinute=.72,gridHeight=(end-start)*pixelsPerMinute;
let hours=Array.from({length:12},(_,i)=>8+i).map(h=>`<div class="hour-marker" style="top:${(h*60-start)*pixelsPerMinute}px"><span>${String(h).padStart(2,'0')}:00</span></div>`).join('');
let columns=providers.map(p=>{const blocks=slots.filter(s=>s.provider_id===p).map(s=>{const y=Math.max(0,(mins(s.start_at)-start)*pixelsPerMinute),h=Math.max(30,(mins(s.end_at)-mins(s.start_at))*pixelsPerMinute);const short=humanService(s);return `<button class="cal-event ${esc(s.status)} ${selected===s.slot_id?'selected':''}" style="top:${y}px;height:${h}px" data-select="${esc(s.slot_id)}"><strong>${time(s.start_at)} ${esc(short)}</strong><small>${esc(s.status==='booked'?state.patient_names[s.booked_patient_id]||s.slot_id:s.slot_id)} · ${s.released_from_cancellation&&s.status==='open'?'Cancelled → open':esc(s.status)}</small></button>`}).join('');return `<div class="pract-column"><div class="pract-title">${esc(p)}</div><div class="pract-lane" style="height:${gridHeight}px">${blocks}</div></div>`}).join('');
const current=state.slots.find(s=>s.slot_id===selected);let detail=current?`<div class="card"><h2>Appointment details</h2>${appointment(current,false)}<div class="divider"></div><div class="row">${current.status==='booked'?`<button class="danger" data-cancel="${esc(current.slot_id)}">Cancel appointment & release opening</button>`:''}${['open','offering','held'].includes(current.status)?`<a class="link-btn" href="${recoveryLink(current.slot_id)}">Open appointment recovery →</a>`:''}</div><p class="muted">Unoccupied space in the calendar is not automatically bookable; the demo does not model full practitioner shifts or rooms.</p></div>`:'';
return `<div class="card"><div class="flex"><h2>Day calendar · ${slots.length} appointments · ${providers.length} practitioners</h2><label class="row muted">Select date <select id="daySelect">${days.map(d=>`<option value="${d}" ${d===day?'selected':''}>${d}</option>`).join('')}</select></label></div><div class="legend">${['booked','open','offering','held','confirmed'].map(pill).join('')}</div><div class="calendar-scroller"><div class="day-calendar" style="--lane-height:${gridHeight}px"><div class="hour-column" style="height:${gridHeight+42}px">${hours}</div>${columns}</div></div></div>${detail}`;}
function humanService(s){return String(s.service_type).replace('physiotherapy','Physio').replace('acupuncture','Acu').replace('massage','Massage');}
function appointments(){return `<section class="card"><div class="flex"><h2>Appointment records</h2><span class="muted">${state.slots.length} total</span></div><p class="muted">Manage booked appointments here. Matching decisions belong only in Appointment Recovery.</p>${[...state.slots].sort((a,b)=>a.start_at.localeCompare(b.start_at)).map(s=>appointment(s)).join('')}</section>`;}
async function recovery(){let openings=state.slots.filter(s=>['open','offering','held','confirmed'].includes(s.status));if(!openings.length)return '<section class="card"><h2>No recovery cases yet</h2><p>Visit the Schedule, cancel a booked appointment, then return here to inspect patient matches.</p><a class="link-btn" href="/clinic/schedule">Go to schedule →</a></section>';
if(!openings.some(s=>s.slot_id===selected))selected=openings[0].slot_id;let s=state.slots.find(s=>s.slot_id===selected);
let html=`<div class="grid recovery-layout"><section class="card"><h2>Openings & recovery cases</h2>${openings.map(x=>`<button class="case-button ${x.slot_id===selected?'case-selected':''}" data-select="${esc(x.slot_id)}"><strong>${esc(x.slot_id)} · ${nice(x.service_type)}</strong><span class="muted">${time(x.start_at)} · ${esc(x.provider_id)}</span>${pill(x.status)}</button>`).join('')}</section><section class="card"><div class="flex"><h2>${esc(s.slot_id)} · ${nice(s.service_type)}</h2>${pill(s.status)}</div><p class="muted">${esc(prettyDate(s.start_at))} · ${time(s.start_at)}–${time(s.end_at)} · ${esc(s.provider_id)}</p>`;
if(s.status==='held'){html+=`<div class="notice">Patient ${esc(state.patient_names[s.winner]||s.winner)} has accepted. Awaiting clinic confirmation.</div><a class="link-btn" href="/clinic/approvals">Open approvals →</a>`;}
else if(s.status==='confirmed'){html+=`<div class="notice">Confirmed for ${esc(s.winner)}. Other offers have closed.</div>`;}
else{const m=await req('/api/clinic/matches/'+encodeURIComponent(selected)+'?clinic='+encodeURIComponent(clinicId));html+=`<div class="flex"><strong>${m.eligible.length} eligible · ${m.excluded.length} excluded</strong><span class="muted">Rules-based eligibility · score is preference fit (not acceptance probability)</span></div><div class="tabs"><button data-tab="eligible" class="${tab==='eligible'?'active':''}">Ranked (${m.eligible.length})</button><button data-tab="excluded" class="${tab==='excluded'?'active':''}">Excluded (${m.excluded.length})</button></div>`;html+=m[tab].slice(0,20).map((p,i)=>`<div class="match"><div class="flex"><strong>${i+1}. ${esc(p.display_name||p.patient_id)} <small>(${esc(p.patient_id)})</small></strong>${p.score!==undefined?`<span class="score">${p.score}/100</span>`:''}</div><div class="reason">${p.reasons.map(esc).join(' · ')}</div></div>`).join('')||'<div class="blank">No candidates in this category.</div>';html+=`<p><button data-send="${esc(selected)}">Send next 3 simulated offers</button></p>`;}
const offers=state.offers.filter(o=>o.slot_id===selected);
if(s.status==='offering' || s.status==='open') html+=`<div class="hint">Simulated current time: ${esc(s.simulation_now||s.released_at)} · Wave ${esc(s.wave||0)}. Maximum 20-minute offer window, shortened if travel time requires it.</div><div class="row"><button class="secondary" data-advance="${esc(selected)}">Advance demo clock 20 min</button></div>`;
if(offers.length)html+=`<div class="divider"></div><h3>Offer activity</h3>${offers.map(o=>`<div class="appointment-row"><span>${esc(state.patient_names[o.patient_id]||o.patient_id)} · ${esc(o.id)}</span>${pill(o.state)}${o.expires_at?` <small>Ends ${esc(o.expires_at.slice(-5))} · wave ${esc(o.wave||1)}</small>`:''}</div>`).join('')}`;
return html+'</section></div>';}
function approvals(){const held=state.slots.filter(s=>s.status==='held'),confirmed=state.slots.filter(s=>s.status==='confirmed');return `<section class="card"><h2>Awaiting clinic approval</h2><p class="muted">In this demo every accepted offer is held until a clinic operator confirms it.</p>${held.length?held.map(s=>`<div class="appointment-row"><div><strong>${esc(s.slot_id)} · ${nice(s.service_type)}</strong><div class="muted">Patient ${esc(state.patient_names[s.winner]||s.winner)} · ${time(s.start_at)} · ${esc(s.provider_id)}${s.status==='booked'&&s.booked_patient_id?' · Patient: '+esc(state.patient_names[s.booked_patient_id]||s.booked_patient_id):''}</div></div><div class="row">${pill(s.status)}<button data-confirm="${esc(s.slot_id)}">Confirm booking</button></div></div>`).join(''):'<div class="blank">No appointments awaiting confirmation.</div>'}</section><section class="card" style="margin-top:16px"><h2>Recently confirmed</h2>${confirmed.length?confirmed.map(s=>appointment(s,false)).join(''):'<div class="blank">No confirmations yet.</div>'}</section>`;}
async function refresh(){try{state=await req('/api/clinic/state?clinic='+encodeURIComponent(clinicId));$('clinicSelect').value=clinicId;const first=state.slots[0];if(!state.slots.some(s=>s.slot_id===selected)) selected=first?.slot_id||'';let out;if(route.includes('schedule'))out=makeCalendar();else if(route.includes('appointments'))out=appointments();else if(route.includes('matching'))out=await recovery();else if(route.includes('approvals'))out=approvals();else out=dashboard();$('clinicContent').innerHTML=out;bind();}catch(e){$('error').textContent=e.message;}}
function bind(){document.querySelectorAll('a[href^="/clinic/"]').forEach(a=>{const u=new URL(a.href);u.searchParams.set('clinic',clinicId);a.href=u.pathname+u.search;});document.querySelectorAll('[data-cancel]').forEach(e=>e.onclick=()=>act('cancel',e.dataset.cancel));document.querySelectorAll('[data-send]').forEach(e=>e.onclick=()=>act('send',e.dataset.send));document.querySelectorAll('[data-advance]').forEach(e=>e.onclick=()=>advance(e.dataset.advance));document.querySelectorAll('[data-confirm]').forEach(e=>e.onclick=()=>act('confirm',e.dataset.confirm));document.querySelectorAll('[data-select]').forEach(e=>e.onclick=()=>{selected=e.dataset.select;refresh();});document.querySelectorAll('[data-tab]').forEach(e=>e.onclick=()=>{tab=e.dataset.tab;refresh();});if($('daySelect'))$('daySelect').onchange=e=>{day=e.target.value;selected=state.slots.find(s=>s.start_at.startsWith(day))?.slot_id||selected;refresh();};}
$('clinicSelect').value=clinicId;$('clinicSelect').onchange=e=>{clinicId=e.target.value;localStorage.setItem('octopus_clinic',clinicId);selected='';day='';history.replaceState(null,'',route+'?clinic='+encodeURIComponent(clinicId));refresh();};refresh();setInterval(()=>{if(!document.hidden)refresh();},6000);

async function advance(slot_id){try{await req('/api/clinic/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'advance',slot_id,minutes:20,clinic_id:clinicId})});$('error').textContent='';await refresh();}catch(e){$('error').textContent=e.message;}}
